/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: databaseDouble
 * Tests
 *   - index migration is additive, repeatable, and records its verified revision
 *   - receipt collection creation accepts only NamespaceExists code and fails safely before index writes
 *   - mandatory index failure prevents migration success without disclosing database errors
 *   - the metadata lookup worker index is required
 *   - essential social cleanup indexes must exist before startup can complete
 *   - the email-link cleanup index must exist before startup can complete
 *   - social cleanup indexes reject unique, sparse, partial, hidden and expiring substitutes
 *   - report deduplication and deletion cleanup indexes are mandatory, while the triage sort index is optional
 *   - nonunique, sparse, partial, and incompatible collation constraints fail verification
 *   - the cover cancellation receipt index requires both declared string predicates
 *   - the cover upload bound and cleanup claim indexes are required
 *   - the MusicBrainz ID indexes are required, unique and partial on stored strings only
 *   - a dropped required index makes a previously initialized database unready
 *   - optional performance-index failure preserves required constraints and emits bounded diagnostics
 *   - the lookup cover worker index is optional: its failure is a bounded diagnostic and needs no required-index revision
 *   - a failed metadata read does not finish verification while another read occupies the pool
 * @end-catalog */

import assert from 'node:assert/strict';
import test from 'node:test';
import type { Db, Document } from 'mongodb';
import {
  databaseIndexes, DatabaseCollectionInitializationError, DatabaseIndexInitializationError, initializeDatabaseIndexes,
  requiredIndexRevision, verifyRequiredDatabaseIndexes
} from '../../src/infrastructure/databaseIndexes';

/** Simulates server index metadata without opening a network connection. */
const databaseDouble = () => {
  const metadata = new Map<string, Document[]>();
  const receipts: string[] = [];
  const collections = new Set<string>();
  const collectionAttempts: string[] = [];
  let failCreate: string | undefined;
  const db = {
    createCollection: async (name: string, options: Document) => {
      collectionAttempts.push(name);
      assert.deepEqual(options, { maxTimeMS: 5_000 });
      if (collections.has(name)) throw Object.assign(new Error('NamespaceExists'), { code: 48 });
      collections.add(name);
    },
    collection: (name: string) => ({
    createIndex: async (key: unknown, options: Document) => {
      if (name === failCreate) throw new Error('private-email@example.test');
      const indexes = metadata.get(name) ?? [];
      if (!indexes.some(index => JSON.stringify(index.key) === JSON.stringify(key))) {
        indexes.push({ key: structuredClone(key), ...structuredClone(options) });
        metadata.set(name, indexes);
      }
    },
    listIndexes: () => ({ toArray: async () => metadata.get(name) ?? [] }),
    updateOne: async (filter: { _id: string }) => { receipts.push(filter._id); }
  }) } as unknown as Db;
  return { db, metadata, receipts, collections, collectionAttempts, fail: (name: string) => { failCreate = name; } };
};

test('index migration is additive, repeatable, and records its verified revision', async () => {
  const fake = databaseDouble();
  await initializeDatabaseIndexes(fake.db);
  await initializeDatabaseIndexes(fake.db);
  assert.deepEqual(fake.receipts, [requiredIndexRevision, requiredIndexRevision]);
  assert.equal([...fake.metadata.values()].flat().length, databaseIndexes.length);
  assert.deepEqual([...fake.collections], ['catalogDeletionOperations']);
  assert.deepEqual(fake.collectionAttempts, ['catalogDeletionOperations', 'catalogDeletionOperations']);
  await verifyRequiredDatabaseIndexes(fake.db);
  assert.equal(fake.collectionAttempts.length, 2);
});

test('receipt collection creation accepts only NamespaceExists code and fails safely before index writes', async () => {
  for (const error of [
    Object.assign(new Error('private permission detail'), { code: 13 }),
    Object.assign(new Error('private creation detail'), { code: 91 }),
    Object.assign(new Error('NamespaceExists private detail'), { codeName: 'NamespaceExists' }),
    Object.assign(new Error('private string code'), { code: '48' })
  ]) {
    const fake = databaseDouble();
    fake.db.createCollection = async () => { throw error; };
    await assert.rejects(initializeDatabaseIndexes(fake.db), failure => {
      assert.ok(failure instanceof DatabaseCollectionInitializationError);
      assert.equal(failure.code, 'database_collection_unavailable');
      assert.equal(failure.message, 'Required database collection is unavailable: catalogDeletionOperations');
      assert.equal('cause' in failure, false);
      return true;
    });
    assert.equal(fake.metadata.size, 0);
    assert.deepEqual(fake.receipts, []);
  }
});

test('mandatory index failure prevents migration success without disclosing database errors', async () => {
  const fake = databaseDouble();
  fake.fail('users');
  await assert.rejects(initializeDatabaseIndexes(fake.db), error => {
    assert.ok(error instanceof DatabaseIndexInitializationError);
    assert.equal(error.indexId, 'users:email');
    assert.equal(String(error).includes('private-email'), false);
    return true;
  });
  assert.deepEqual(fake.receipts, []);
});

test('the metadata lookup worker index is required', async () => {
  const fake = databaseDouble();
  fake.fail('adminImportLookups');
  await assert.rejects(initializeDatabaseIndexes(fake.db), (error: unknown) => {
    assert.ok(error instanceof DatabaseIndexInitializationError);
    assert.equal(error.indexId, 'adminImportLookups:state,leaseUntil,retryAt');
    return true;
  });
  assert.deepEqual(fake.receipts, []);
});

test('essential social cleanup indexes must exist before startup can complete', async () => {
  for (const collection of ['socialRelationships', 'socialHandles', 'socialMusicShares', 'socialListeningPublications', 'socialReports']) {
    const fake = databaseDouble();
    fake.fail(collection);
    await assert.rejects(initializeDatabaseIndexes(fake.db), DatabaseIndexInitializationError);
    assert.deepEqual(fake.receipts, []);
  }
});

test('the email-link cleanup index must exist before startup can complete', async () => {
  const fake = databaseDouble();
  fake.fail('emailLinkTokens');
  await assert.rejects(initializeDatabaseIndexes(fake.db), (error: unknown) => {
    assert.ok(error instanceof DatabaseIndexInitializationError);
    assert.equal(error.indexId, 'emailLinkTokens:email,purpose');
    return true;
  });
  assert.deepEqual(fake.receipts, []);

  const initialized = databaseDouble();
  await initializeDatabaseIndexes(initialized.db);
  initialized.metadata.set('emailLinkTokens', []);
  await assert.rejects(verifyRequiredDatabaseIndexes(initialized.db), /emailLinkTokens:email,purpose/);
});

test('social cleanup indexes reject unique, sparse, partial, hidden and expiring substitutes', async () => {
  for (const altered of [
    { unique: true }, { sparse: true }, { partialFilterExpression: { active: true } },
    { hidden: true }, { expireAfterSeconds: 0 }, { collation: { locale: 'en' } }
  ]) {
    const fake = databaseDouble();
    await initializeDatabaseIndexes(fake.db);
    Object.assign(fake.metadata.get('socialRelationships')![0], altered);
    await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), /socialRelationships:accountIds/);
  }
  const fake = databaseDouble();
  await initializeDatabaseIndexes(fake.db);
  fake.metadata.set('socialHandles', []);
  await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), /socialHandles:accountId/);
});

test('report deduplication and deletion cleanup indexes are mandatory, while the triage sort index is optional', async () => {
  const initialized = databaseDouble();
  await initializeDatabaseIndexes(initialized.db);
  const keys = initialized.metadata.get('socialReports')!.map(index => JSON.stringify(index.key));
  for (const expected of [{ dedupeKey: 1 }, { reporterAccountId: 1 }, { targetAccountId: 1, state: 1 }]) {
    assert.ok(keys.includes(JSON.stringify(expected)), JSON.stringify(expected));
  }
  for (const [kept, pattern] of [
    [(index: Document) => JSON.stringify(index.key) !== JSON.stringify({ dedupeKey: 1 }), /socialReports:dedupeKey/],
    [(index: Document) => JSON.stringify(index.key) !== JSON.stringify({ targetAccountId: 1, state: 1 }), /socialReports:targetAccountId,state/]
  ] as const) {
    const fake = databaseDouble();
    await initializeDatabaseIndexes(fake.db);
    fake.metadata.set('socialReports', fake.metadata.get('socialReports')!.filter(kept));
    await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), pattern);
  }
  const optional = databaseDouble();
  await initializeDatabaseIndexes(optional.db);
  optional.metadata.set('socialReports', optional.metadata.get('socialReports')!
    .filter(index => JSON.stringify(index.key) !== JSON.stringify({ state: 1, createdAt: 1, _id: 1 })));
  await verifyRequiredDatabaseIndexes(optional.db);
});

test('nonunique, sparse, partial, and incompatible collation constraints fail verification', async () => {
  for (const altered of [
    { unique: false }, { sparse: true }, { partialFilterExpression: { active: true } },
    { collation: { locale: 'en', strength: 2 } }
  ]) {
    const fake = databaseDouble();
    await initializeDatabaseIndexes(fake.db);
    Object.assign(fake.metadata.get('users')![0], altered);
    await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), DatabaseIndexInitializationError);
  }
});

test('the cover cancellation receipt index requires both declared string predicates', async () => {
  const fake = databaseDouble(); await initializeDatabaseIndexes(fake.db);
  const index = fake.metadata.get('adminCatalogCoverOperations')!.find(index => 'cancellation.actor' in index.key)!;
  await verifyRequiredDatabaseIndexes(fake.db);
  index.partialFilterExpression = { 'cancellation.actor': { $type: 'string' } };
  await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), /cancellation.actor,cancellation.operationId/);
});

test('the cover upload bound and cleanup claim indexes are required', async () => {
  const declared = databaseIndexes.filter(index => index.collection === 'adminCatalogCoverUploads');
  assert.deepEqual(declared.map(index => [index.keys, index.required, index.options]),
    [[{ actorId: 1, usedBy: 1, 'asset.state': 1 }, true, undefined], [{ 'asset.state': 1, leaseUntil: 1 }, true, undefined]]);
  for (const [key, indexId] of [['actorId', 'adminCatalogCoverUploads:actorId,usedBy,asset.state'], ['leaseUntil', 'adminCatalogCoverUploads:asset.state,leaseUntil']] as const) {
    const fake = databaseDouble(); await initializeDatabaseIndexes(fake.db);
    const indexes = fake.metadata.get('adminCatalogCoverUploads')!;
    assert.equal(indexes.length, 2);
    await verifyRequiredDatabaseIndexes(fake.db);
    fake.metadata.set('adminCatalogCoverUploads', indexes.filter(index => !(key in index.key)));
    await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), (error: unknown) => error instanceof DatabaseIndexInitializationError && error.indexId === indexId);
  }
});

test('the MusicBrainz ID indexes are required, unique and partial on stored strings only', async () => {
  for (const collection of ['artists', 'organizations']) {
    const fake = databaseDouble(); await initializeDatabaseIndexes(fake.db);
    const index = () => fake.metadata.get(collection)!.find(entry => 'musicBrainzId' in entry.key)!;
    assert.deepEqual(index().partialFilterExpression, { musicBrainzId: { $type: 'string' } });
    assert.equal(index().unique, true);
    assert.equal(index().name, collection === 'artists' ? 'artist_musicbrainz_id' : 'organization_musicbrainz_id');
    await verifyRequiredDatabaseIndexes(fake.db);
    // A sparse, non-partial or non-unique substitute cannot stand in for the declared constraint.
    for (const altered of [{ sparse: true }, { partialFilterExpression: undefined }, { unique: false }, { partialFilterExpression: { musicBrainzId: { $exists: true } } }]) {
      const entry = index(), original = structuredClone(entry);
      Object.assign(entry, altered);
      await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), new RegExp(`${collection}:musicBrainzId`));
      for (const key of Object.keys(entry)) delete entry[key];
      Object.assign(entry, original);
      await verifyRequiredDatabaseIndexes(fake.db);
    }
    // Startup fails closed (existing duplicates refuse the unique index) and records no revision.
    const failing = databaseDouble(); failing.fail(collection);
    await assert.rejects(initializeDatabaseIndexes(failing.db), DatabaseIndexInitializationError);
    assert.deepEqual(failing.receipts, []);
  }
  assert.equal(requiredIndexRevision, 'required-indexes-v12-catalog-cover-uploads');
});

test('a dropped required index makes a previously initialized database unready', async () => {
  const fake = databaseDouble();
  await initializeDatabaseIndexes(fake.db);
  fake.metadata.set('passkeys', []);
  await assert.rejects(verifyRequiredDatabaseIndexes(fake.db), /passkeys:credentialId/);
});

test('optional performance-index failure preserves required constraints and emits bounded diagnostics', async () => {
  const fake = databaseDouble();
  fake.fail('posts');
  const entries: string[] = [];
  const warn = console.warn;
  console.warn = (entry: string) => { entries.push(entry); };
  try { await initializeDatabaseIndexes(fake.db); } finally { console.warn = warn; }
  assert.deepEqual(entries.map(entry => JSON.parse(entry)), [
    { category: 'optional_index_unavailable', indexId: 'posts:createdAt' }
  ]);
  assert.equal(fake.receipts.length, 1);
});

test('the lookup cover worker index is optional: its failure is a bounded diagnostic and needs no required-index revision', async () => {
  const declared = databaseIndexes.filter(index => index.options?.name === 'admin_import_lookup_cover_worker');
  assert.deepEqual(declared.map(index => [index.collection, index.keys, Boolean(index.required || index.options?.unique)]),
    [['adminAlbumImports', { 'media.lookupCover.due': 1, 'media.lookupCover.leaseUntil': 1 }, false]]);
  assert.equal(requiredIndexRevision, 'required-indexes-v12-catalog-cover-uploads');
  const fake = databaseDouble(), collection = fake.db.collection.bind(fake.db);
  (fake.db as unknown as { collection: unknown }).collection = (name: string) => {
    const target = collection(name);
    return { ...target, createIndex: async (key: Document, options: Document) => {
      if (options?.name === 'admin_import_lookup_cover_worker') throw new Error('private-email@example.test');
      return target.createIndex(key, options);
    } };
  };
  const entries: string[] = [];
  const warn = console.warn;
  console.warn = (entry: string) => { entries.push(entry); };
  try { await initializeDatabaseIndexes(fake.db); } finally { console.warn = warn; }
  assert.deepEqual(entries.map(entry => JSON.parse(entry)), [
    { category: 'optional_index_unavailable', indexId: 'adminAlbumImports:media.lookupCover.due,media.lookupCover.leaseUntil' }
  ]);
  assert.equal(fake.receipts.length, 1);
  await verifyRequiredDatabaseIndexes(fake.db);
});

test('a failed metadata read does not finish verification while another read occupies the pool', async () => {
  let release!: () => void;
  let entered!: () => void;
  const started = new Promise<void>(resolve => { entered = resolve; });
  let settled = false;
  const db = { collection: (name: string) => ({ listIndexes: () => ({ toArray: async () => {
    if (name === 'users') throw new Error('synthetic failure');
    if (name === 'pages') {
      entered();
      await new Promise<void>(resolve => { release = resolve; });
    }
    return [];
  } }) }) } as unknown as Db;
  const checked = verifyRequiredDatabaseIndexes(db).then(() => { settled = true; }, () => { settled = true; });
  await started;
  await new Promise(resolve => setImmediate(resolve));
  assert.equal(settled, false);
  release();
  await checked;
  assert.equal(settled, true);
});
